import pytest

from bedrock_protocol import v975, v1001

# generated by gophertunnel de090ae:
# packet.ClientCacheBlobStatus{MissHashes: []uint64{1, 2}, HitHashes: []uint64{3}}
V975 = bytes.fromhex("0201010000000000000002000000000000000300000000000000")

# generated by gophertunnel 654cd5f:
# packet.ClientCacheBlobStatus{MissHashes: []uint64{1, 2}, HitHashes: []uint64{3}}
V1001 = bytes.fromhex("0201000000000000000200000000000000010300000000000000")

# generated by gophertunnel de090ae and 654cd5f:
# packet.ClientCacheBlobStatus{}
EMPTY = bytes.fromhex("0000")

GOLDENS = [
    pytest.param(
        v975.ClientCacheBlobStatusPacket(missing_count=2, found_count=1, missing_ids=[1, 2], found_ids=[3]),
        V975,
        id="v975",
    ),
    pytest.param(v1001.ClientCacheBlobStatusPacket(missing_ids=[1, 2], found_ids=[3]), V1001, id="v1001"),
    pytest.param(v975.ClientCacheBlobStatusPacket(), EMPTY, id="v975-empty"),
    pytest.param(v1001.ClientCacheBlobStatusPacket(), EMPTY, id="v1001-empty"),
]


@pytest.mark.parametrize("version", [v975, v1001])
def test_client_cache_blob_status_is_packet_135(version):
    assert version.packets[135] is version.ClientCacheBlobStatusPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_client_cache_blob_status_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_client_cache_blob_status_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
